157	func newFlagSet(name string) *flag.FlagSet {
158		fs := flag.NewFlagSet(name, flag.ContinueOnError)
159		fs.SetOutput(os.Stderr)
160		fs.Usage = func() { heartbeatUsage() }
161		return fs
162	}
