164	func cmdSubmit(args []string) {
165		fs := newFlagSet("heartbeat submit")
166		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
167		receiveStr := fs.String("receive-time", "", "receive time (RFC3339); default: now")
168		if err := fs.Parse(args); err != nil {
169			if err == flag.ErrHelp {
170				os.Exit(0)
171			}
172			os.Exit(2)
173		}
174		if fs.NArg() != 0 {
175			die("submit takes no positional arguments; heartbeats are read from stdin")
176		}
177	
178		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
179	
180		data, err := io.ReadAll(os.Stdin)
181		if err != nil {
182			die("cannot read stdin: %v", err)
183		}
184		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
185		if err != nil {
186			die("invalid input: %v", err)
187		}
188	
189		store, err := edgefleet.OpenStore(*dataDir)
190		if err != nil {
191			die("%v", err)
192		}
193		newCount, dupCount, err := store.Submit(records, receiveTime)
194		if err != nil {
195			die("%v", err)
196		}
197		fmt.Printf("submitted: new=%d duplicate=%d\n", newCount, dupCount)
198	}
