200	func cmdHealth(args []string) {
201		fs := newFlagSet("heartbeat health")
202		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
203		node := fs.String("node", "", "node id (required)")
204		atStr := fs.String("at", "", "query time (RFC3339); default: now")
205		expectedVersion := fs.String("expected-version", "", "expected version (required)")
206		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
207		missedSinceSeq := fs.Int64("missed-since-seq", 0, "seq of a saved heartbeat to use as the missed-duty baseline; must be > 0 and exist for the node")
208		if err := fs.Parse(args); err != nil {
209			if err == flag.ErrHelp {
210				os.Exit(0)
211			}
212			os.Exit(2)
213		}
214		if *node == "" {
215			die("--node is required")
216		}
217		if *expectedVersion == "" {
218			die("--expected-version is required")
219		}
220		if *toleratedMisses < 0 {
221			die("--tolerated-misses is required and must be >= 0")
222		}
223		if isFlagPassed(fs, "missed-since-seq") && *missedSinceSeq <= 0 {
224			die("--missed-since-seq must be a positive integer")
225		}
226	
227		at := parseTimeFlag(*atStr, "--at")
228	
229		store, err := edgefleet.OpenStore(*dataDir)
230		if err != nil {
231			die("%v", err)
232		}
233	
234		var result edgefleet.HealthResult
235		if isFlagPassed(fs, "missed-since-seq") {
236			result, err = store.HealthSince(*node, at, *expectedVersion, *toleratedMisses, *missedSinceSeq)
237		} else {
238			result, err = store.Health(*node, at, *expectedVersion, *toleratedMisses)
239		}
240		if err != nil {
241			die("%v", err)
242		}
243	
244		// Node id and version go through the shared display rule: text that would
245		// break the one-line format (newlines, tabs, quotes, backslashes, control
246		// characters) is shown as a quoted JSON string, so a health query always
247		// prints exactly one line — two with a missed-duty baseline — and node
248		// text can never masquerade as extra fields or a second result line.
249		if result.Status == "notelemetry" {
250			fmt.Printf("node=%s status=无遥测 findings=[无遥测]\n", edgefleet.DisplayText(result.NodeID))
251			return
252		}
253		fmt.Printf("node=%s status=%s seq=%d collected_at=%s version=%s height=%d missed=%d findings=%v\n",
254			edgefleet.DisplayText(result.NodeID), result.Status, result.Seq, result.CollectedAt.Format(time.RFC3339),
255			edgefleet.DisplayText(result.Version), result.Height, result.Missed, result.Findings)
256		if isFlagPassed(fs, "missed-since-seq") {
257			// missed above stays cumulative; this line states the alarm basis.
258			if result.NewMissedKnown {
259				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=%d tolerated_misses=%d\n",
260					result.BaselineSeq, result.BaselineMissed, result.NewMissed, *toleratedMisses)
261			} else {
262				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=无法判断 tolerated_misses=%d\n",
263					result.BaselineSeq, result.BaselineMissed, *toleratedMisses)
264			}
265		}
266	}
267	
268	// isFlagPassed reports whether the named flag was explicitly set on the
269	// command line, so an optional flag with a zero default can be distinguished
270	// from its absence.
271	func isFlagPassed(fs *flag.FlagSet, name string) bool {
272		passed := false
273		fs.Visit(func(f *flag.Flag) {
274			if f.Name == name {
275				passed = true
276			}
277		})
278		return passed
279	}
280	
281	func cmdHistory(args []string) {
282		fs := newFlagSet("heartbeat history")
283		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
284		node := fs.String("node", "", "node id (required)")
285		if err := fs.Parse(args); err != nil {
286			if err == flag.ErrHelp {
287				os.Exit(0)
288			}
289			os.Exit(2)
290		}
291		if *node == "" {
292			die("--node is required")
293		}
294	
295		store, err := edgefleet.OpenStore(*dataDir)
296		if err != nil {
297			die("%v", err)
298		}
299		records, err := store.History(*node)
300		if err != nil {
301			die("%v", err)
302		}
303		if len(records) == 0 {
304			fmt.Printf("node=%s no heartbeats\n", *node)
305			return
306		}
307		for _, r := range records {
308			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
309				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
310		}
311	}
312	
313	func runDemo() {
314		nodes := []edgefleet.Node{
315			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
316			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
317			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
318		}
319		unhealthy := 0
320		for _, node := range nodes {
321			health := edgefleet.Evaluate(node, "1.26.0", 1)
322			if !health.Healthy {
323				unhealthy++
324			}
325			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
326		}
327		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
328		fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
329	}
