51	func TestMain(m *testing.M) {
52		if os.Getenv(cliTestEnv) == "1" {
53			// Run the genuine command entry point and let its own os.Exit calls
54			// determine the helper process status.
55			main()
56			os.Exit(0)
57		}
58		os.Exit(m.Run())
59	}
