102	func health(t *testing.T, f *fixture, args ...string) (string, string, int) {
103		t.Helper()
104		full := append([]string{"heartbeat", "health", "--data-dir", f.dir, "--at", cliQueryAt}, args...)
105		return runCLI(t, f.dir, "", full...)
106	}
