108	// outputLines splits stdout into lines, treating a trailing newline as no
109	// extra empty line.
110	func outputLines(s string) []string {
111		s = strings.TrimRight(s, "\n")
112		if s == "" {
113			return nil
114		}
115		return strings.Split(s, "\n")
116	}
