862	// TestCLISubmitContentDifferencesConflictAgainstHistory covers every field
863	// that makes a same-node/same-seq record a conflict rather than a duplicate:
864	// version, height, cumulative missed, and the collection instant (including
865	// equal wall-clock text with a different offset, which is a different
866	// instant). Nothing is overwritten and no last-write-wins occurs.
867	func TestCLISubmitContentDifferencesConflictAgainstHistory(t *testing.T) {
868		const base = `{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}`
869		cases := []struct {
870			name string
871			// incoming is the conflicting record, same node+seq as the saved one.
872			incoming string
873		}{
874			{"version differs",
875				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.27.0","height":100,"missed":0}`},
876			{"height differs",
877				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":101,"missed":0}`},
878			{"missed differs",
879				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":1}`},
880			{"collected instant differs",
881				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:58:00Z","version":"1.26.0","height":100,"missed":0}`},
882			{"same wall clock text, different offset is a different instant",
883				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00+08:00","version":"1.26.0","height":100,"missed":0}`},
884		}
885		for _, tc := range cases {
886			t.Run(tc.name, func(t *testing.T) {
887				dir := t.TempDir()
888				// Each subtest gets its own data directory, so one fixed node id
889				// carrying the saved seq-2 baseline is enough.
890				const node = "node"
891				submitBatch(t, dir, "["+fmt.Sprintf(base, node)+"]")
892				before := historyLines(t, dir, node)
893	
894				out, errOut, code := submit(t, dir, "["+fmt.Sprintf(tc.incoming, node)+"]")
895				if code == 0 {
896					t.Fatalf("conflicting record must fail non-zero; stdout=%q", out)
897				}
898				// The error names the node and the seq, and goes to stderr.
899				for _, want := range []string{"error:", "conflict", node, "seq 2"} {
900					if !strings.Contains(errOut, want) {
901						t.Errorf("stderr %q must contain %q", errOut, want)
902					}
903				}
904				// No success line or counters on stdout.
905				if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
906					t.Errorf("rejected batch must not print success counts, stdout=%q", out)
907				}
908				// The original telemetry is intact: not replaced by the incoming
909				// content, not counted as a duplicate.
910				after := historyLines(t, dir, node)
911				if len(after) != 1 || after[0] != before[0] {
912					t.Errorf("history changed after conflict:\nbefore=%q\nafter =%q", before, after)
913				}
914			})
915		}
916	}
