981		// 甲 already saved seq 1 with specific telemetry.
982		submitBatch(t, dir, `[
983		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}
984		]`)
