func TestParseHeartbeatsRecordPosition(t *testing.T) {
	// Error record at index 0 (position 1).
	_, err := ParseHeartbeats([]byte(`[
		{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":null,"missed":0},
